import React, { useState, useEffect } from "react";
import { useNavigate, useParams } from "react-router-dom";

const ResetPassword = (props) => {
  const [passwords, setPasswords] = useState({
    newPassword: "",
    confirmPassword: ""
  });
  const [loading, setLoading] = useState(false);
  const [tokenValid, setTokenValid] = useState(true);
  const navigate = useNavigate();
  const { token } = useParams();
  const host = "http://localhost:5000";

  useEffect(() => {
    // Verify token validity on component mount
    verifyToken();
  }, [token]);

  const verifyToken = async () => {
    try {
      const response = await fetch(`${host}/api/auth/verify-reset-token/${token}`, {
        method: "GET",
        headers: {
          "Content-Type": "application/json",
        }
      });

      if (!response.ok) {
        setTokenValid(false);
        props.showAlert("Invalid or expired reset token", "danger");
      }
    } catch (error) {
      console.error('Error verifying token:', error);
      setTokenValid(false);
      props.showAlert("Error verifying reset token", "danger");
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    
    if (passwords.newPassword !== passwords.confirmPassword) {
      props.showAlert("Passwords don't match", "danger");
      return;
    }

    if (passwords.newPassword.length < 5) {
      props.showAlert("Password must be at least 5 characters long", "danger");
      return;
    }

    setLoading(true);

    try {
      const response = await fetch(`${host}/api/auth/reset-password`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          token,
          newPassword: passwords.newPassword
        }),
      });

      const result = await response.json();
      
      if (response.ok) {
        props.showAlert("Password reset successfully! Please login with your new password.", "success");
        navigate("/login");
      } else {
        props.showAlert(result.message || "Failed to reset password", "danger");
      }
    } catch (error) {
      console.error('Error resetting password:', error);
      props.showAlert("Error resetting password", "danger");
    } finally {
      setLoading(false);
    }
  };

  const onChange = (e) => {
    setPasswords({ ...passwords, [e.target.name]: e.target.value });
  };

  if (!tokenValid) {
    return (
      <div className="container mt-5">
        <div className="row justify-content-center">
          <div className="col-md-6">
            <div className="card">
              <div className="card-body text-center">
                <div className="mb-4">
                  <i className="fas fa-exclamation-triangle fa-4x text-danger"></i>
                </div>
                <h3 className="card-title">Invalid Reset Link</h3>
                <p className="card-text">
                  This password reset link is invalid or has expired.
                </p>
                <div className="d-grid gap-2">
                  <button 
                    className="btn btn-primary"
                    onClick={() => navigate("/forgot-password")}
                  >
                    Request New Reset Link
                  </button>
                  <button 
                    className="btn btn-outline-secondary"
                    onClick={() => navigate("/login")}
                  >
                    Back to Login
                  </button>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="container mt-5">
      <div className="row justify-content-center">
        <div className="col-md-6">
          <div className="card">
            <div className="card-header text-center">
              <h2 className="mb-0">
                <i className="fas fa-lock me-2"></i>Reset Password
              </h2>
            </div>
            <div className="card-body">
              <p className="text-muted text-center mb-4">
                Enter your new password below.
              </p>
              
              <form onSubmit={handleSubmit}>
                <div className="mb-3">
                  <label htmlFor="newPassword" className="form-label">
                    <i className="fas fa-key me-2"></i>New Password
                  </label>
                  <input
                    type="password"
                    className="form-control"
                    id="newPassword"
                    name="newPassword"
                    value={passwords.newPassword}
                    onChange={onChange}
                    placeholder="Enter new password"
                    minLength={5}
                    required
                  />
                  <div className="form-text">Password must be at least 5 characters long</div>
                </div>

                <div className="mb-3">
                  <label htmlFor="confirmPassword" className="form-label">
                    <i className="fas fa-check-circle me-2"></i>Confirm New Password
                  </label>
                  <input
                    type="password"
                    className="form-control"
                    id="confirmPassword"
                    name="confirmPassword"
                    value={passwords.confirmPassword}
                    onChange={onChange}
                    placeholder="Confirm new password"
                    minLength={5}
                    required
                  />
                </div>

                {/* Password Match Indicator */}
                {passwords.newPassword && passwords.confirmPassword && (
                  <div className="mb-3">
                    {passwords.newPassword === passwords.confirmPassword ? (
                      <small className="text-success">
                        <i className="fas fa-check me-1"></i>Passwords match
                      </small>
                    ) : (
                      <small className="text-danger">
                        <i className="fas fa-times me-1"></i>Passwords don't match
                      </small>
                    )}
                  </div>
                )}

                <div className="d-grid">
                  <button 
                    type="submit" 
                    className="btn btn-primary"
                    disabled={
                      loading || 
                      !passwords.newPassword || 
                      !passwords.confirmPassword ||
                      passwords.newPassword !== passwords.confirmPassword ||
                      passwords.newPassword.length < 5
                    }
                  >
                    {loading ? (
                      <>
                        <span className="spinner-border spinner-border-sm me-2" role="status"></span>
                        Resetting...
                      </>
                    ) : (
                      <>
                        <i className="fas fa-save me-2"></i>Reset Password
                      </>
                    )}
                  </button>
                </div>
              </form>

              <div className="text-center mt-3">
                <button 
                  className="btn btn-link text-decoration-none"
                  onClick={() => navigate("/login")}
                >
                  <i className="fas fa-arrow-left me-1"></i>Back to Login
                </button>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default ResetPassword;
